  netKpi.textContent = '$' + gross.toLocaleString('en-US');
  savingsKpi.textContent = '$0';
  banner.style.background = 'rgba(16, 185, 129, 0.14)';
  banner.style.borderColor = 'rgba(16, 185, 129, 0.4)';
